"""Verify the lossless recovery archive, or restore only missing original JSON files."""
import argparse
import gzip
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = Path(__file__).resolve().parents[4]


def digest(data):
    return hashlib.sha256(data).hexdigest()


def path_in_root(name):
    path = (ROOT / name).resolve()
    if not path.is_relative_to(ROOT):
        raise ValueError('Manifest path is outside the repository: ' + name)
    return path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--restore', action='store_true', help='Restore missing originals; never overwrite an existing file')
    args = parser.parse_args()
    manifest = json.loads((HERE / 'manifest.json').read_text())
    if manifest.get('format') != 1 or manifest.get('encoding') != 'gzip':
        raise ValueError('Unsupported recovery manifest')
    result = []
    for item in manifest['records']:
        compressed = path_in_root(item['compressedPath']).read_bytes()
        if len(compressed) != item['compressedBytes'] or digest(compressed) != item['compressedSha256']:
            raise ValueError('Compressed artifact changed: ' + item['compressedPath'])
        data = gzip.decompress(compressed)
        if len(data) != item['rawBytes'] or digest(data) != item['rawSha256']:
            raise ValueError('Uncompressed artifact does not match its original: ' + item['rawPath'])
        raw = path_in_root(item['rawPath'])
        restored = False
        if raw.exists():
            if raw.read_bytes() != data:
                raise ValueError('Existing original differs; it was preserved unchanged: ' + str(raw))
        elif args.restore:
            raw.parent.mkdir(parents=True, exist_ok=True)
            with raw.open('xb') as stream:
                stream.write(data)
            restored = True
        result.append({'path': item['rawPath'], 'bytes': len(data), 'sha256': item['rawSha256'],
                       'compressedVerified': True, 'originalPresent': raw.exists(), 'restored': restored})
    print(json.dumps({'verified': True, 'records': result}, indent=2, sort_keys=True))


if __name__ == '__main__':
    main()
